result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test_peeking.py", "content": """"Tests for the sequential-peeking hazard demo and fixed-horizon analyzer."""

import re

import pytest

from peeking import (
    run_simulations,
    peeking_false_positive_rate,
    fixed_horizon_false_positive_rate,
)


@pytest.fixture(scope="module")
def results():
    return run_simulations()


def test_peeking_inflates_false_positive_rate(results):
    """With 10 interim looks at alpha=0.05, the FPR should far exceed 10%."""
    rate = peeking_false_positive_rate(results)
    assert rate > 0.10, f"peeking FPR {rate:.4f} unexpectedly low"


def test_fixed_horizon_near_nominal(results):
    """The single final look should land within 0.02 of the nominal 0.05."""
    rate = fixed_horizon_false_positive_rate(results)
    assert abs(rate - 0.05) <= 0.02, f"fixed-horizon FPR {rate:.4f} off target"


def _parse_report_rates(text):
    peek_match = re.search(
        r"Sequential peeking false-positive rate:\s*([0-9.]+)", text
    )
    fixed_match = re.search(
        r"Fixed-horizon false-positive rate:\s*([0-9.]+)", text
    )
    assert peek_match, "REPORT.md missing sequential peeking rate"
    assert fixed_match, "REPORT.md missing fixed-horizon rate"
    return float(peek_match.group(1)), float(fixed_match.group(1))


def test_report_matches_recomputed_rates(results):
    """REPORT.md must state exactly the recomputed rates (4 decimal places)."""
    with open("REPORT.md") as f:
        text = f.read()
    stated_peek, stated_fixed = _parse_report_rates(text)

    expected_peek = round(peeking_false_positive_rate(results), 4)
    expected_fixed = round(fixed_horizon_false_positive_rate(results), 4)

    assert stated_peek == pytest.approx(expected_peek, abs=1e-9), (
        f"stated peeking rate {stated_peek} != recomputed {expected_peek}"
    )
    assert stated_fixed == pytest.approx(expected_fixed, abs=1e-9), (
        f"stated fixed-horizon rate {stated_fixed} != recomputed {expected_fixed}"
    )
